mapper.select:
SELECT id, code, name, description, widget_type, data_source,
       data_source_config::text AS data_source_config,
       default_config::text AS default_config,
       available_dimensions, required_role_codes,
       status, created_by, created_at, updated_at
FROM dashboard_widget

    AND widget_type = #{widgetType}
    AND status = #{status}

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM dashboard_widget

    AND widget_type = #{widgetType}
    AND status = #{status}
